const output=process.env.CORE_QUOTA_OUTPUT,quota=Number(process.env.CORE_QUOTA);
const report={quota,cores:[],deferredCount:0,globalLedger:null,globalResult:null};
const pending=[],ledgers=new WeakSet();let active=null;
const save=()=>writeFileSync(output+'-quota.json',JSON.stringify(report,null,2));
const ledgerSnapshot=l=>({limit:l.limit,total:l.branchesExplored,core:l.coreBranches,continuation:l.standaloneBranches,lastExhaustionPhase:l.lastExhaustionPhase});
globalThis.__quotaEnter=(candidate,ledger)=>{
 if(!ledgers.has(ledger)){const original=ledger.consume.bind(ledger);ledger.consume=(phase,count=1)=>{
  if(active&&ledger.branchesExplored+count<=ledger.limit&&ledger.branchesExplored-active.before.total+count>quota){active.localStopped=true;return false;}
  return original(phase,count);
 };ledgers.add(ledger);}
 const row={ordinal:report.cores.length+1,architectureFingerprint:candidate.architectureFingerprint??null,fingerprint:candidate.fingerprint,mainStarts:candidate.tasks.filter(t=>t.kind==='main').map(t=>({id:t.id,start:t.start})),before:ledgerSnapshot(ledger),after:null,localStopped:false,outcome:'RUNNING',wallStart:performance.now()};
 active=row;report.cores.push(row);save();return row;
};
globalThis.__quotaResult=(result,row,ledger,retain)=>{
 if(row.localStopped&&ledger.branchesExplored<ledger.limit){pending.push(retain);report.deferredCount=pending.length;result='DEFERRED';}
 row.after=ledgerSnapshot(ledger);row.consumed={core:row.after.core-row.before.core,continuation:row.after.continuation-row.before.continuation,total:row.after.total-row.before.total};
 row.outcome=result==='DEFERRED'?'DEFERRED_LOCAL_QUOTA':result==='BUDGET_EXHAUSTED'?'GLOBAL_BUDGET_EXHAUSTED':result==='ACCEPT'?'CERTIFIED':typeof result==='object'?'CERTIFIED_BACKJUMP':'DEAD_END_BRANCH';row.wallMs=performance.now()-row.wallStart;delete row.wallStart;report.globalLedger=row.after;save();return result;
};
globalThis.__quotaLeave=()=>{active=null;};
globalThis.__quotaFinal=r=>{report.globalResult={status:r.status,reasonCodes:r.evidence?.reasonCodes,branchesExplored:r.evidence?.branchesExplored,coreBranches:r.evidence?.coreBranches,standaloneBranches:r.evidence?.standaloneBranches};save();return r;};
const fn=n=>ts.isFunctionDeclaration(n)||ts.isFunctionExpression(n)||ts.isArrowFunction(n)||ts.isMethodDeclaration(n);
const name=n=>n.name?.getText()??(ts.isCallExpression(n.parent)&&n.parent.expression.getText()==='__name'?n.parent.arguments[1]?.text:ts.isVariableDeclaration(n.parent)?n.parent.name.getText():null);
registerHooks({load(url,context,nextLoad){const result=nextLoad(url,context);if(!url.endsWith('/exactItinerantPlan.ts')&&!url.endsWith('/exactMainAndFeederCore.ts'))return result;
 let source=typeof result.source==='string'?result.source:Buffer.from(result.source).toString();
 // The diagnostic tag advances enumeration without claiming negative feasibility.
 source=source.replace('evidence.bundleTerminalCause = "UNCERTIFIED_REJECT";', 'evidence.bundleTerminalCause = continuation === "DEFERRED" ? "DEFERRED" : "UNCERTIFIED_REJECT";');
 const tree=ts.createSourceFile('quota.js',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.JS),edits=[];
 const visit=n=>{if(fn(n)&&n.body&&ts.isBlock(n.body)){
  const key=name(n);
  if(key==='onHardValidCoreLeaf'){
   edits.push({pos:n.body.getStart()+1,end:n.body.getStart()+1,text:'const __quotaFrame=globalThis.__quotaEnter(candidate,ledger); try {'});
   edits.push({pos:n.body.end-1,end:n.body.end-1,text:'} finally {globalThis.__quotaLeave();}'});
   const returns=t=>{if(fn(t)&&t!==n)return;if(ts.isReturnStatement(t)&&t.expression)edits.push({pos:t.expression.getStart(),end:t.expression.end,text:` globalThis.__quotaResult((${t.expression.getText()}),__quotaFrame,ledger,()=>({candidate,retained:true}))`});ts.forEachChild(t,returns);};returns(n);
  }
  if(key==='runExactItinerantPlanSearch'){
   const returns=t=>{if(fn(t)&&t!==n)return;if(ts.isReturnStatement(t)&&t.expression)edits.push({pos:t.expression.getStart(),end:t.expression.end,text:` globalThis.__quotaFinal((${t.expression.getText()}))`});ts.forEachChild(t,returns);};returns(n);
  }
 }ts.forEachChild(n,visit);};visit(tree);
 for(const edit of edits.sort((a,b)=>b.pos-a.pos))source=source.slice(0,edit.pos)+edit.text+source.slice(edit.end);
 return {...result,source};}});

