import {writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {runA2Assist8Evidence} from '../../server/benchmarks/runA2Assist8Evidence';
import {collectiveClosureDeterministicMaterial} from '../../server/benchmarks/runA2CollectiveClosureEvidence';
const output=process.argv[2],started=performance.now();
const result=await runA2Assist8Evidence({reportIterationDurations:true,stopAfterIterationCount:1});
const summary={status:result.status,accepted:result.completedObligationCount,stageCount:result.stageCount,wallMs:performance.now()-started,requestMs:result.iterations[0]?.durationMs,work:result.iterations[0]?.work,blocker:result.firstBlocker,materialDigest:createHash('sha256').update(JSON.stringify(collectiveClosureDeterministicMaterial(result))).digest('hex')};
