console.log(JSON.stringify({status:summary.status,accepted:summary.accepted,stageCount:summary.stageCount,wallMs:summary.wallMs,requestMs:summary.requestMs,branches:summary.work?.branchesExplored,blocker:summary.blocker?.rejectionReason}));

