const output=process.argv[2],started=performance.now();
const result=await runA2Assist8Evidence({reportIterationDurations:true});
const stages=result.iterations.map((stage:any)=>({ordinal:stage.ordinal,outcome:stage.proposalOutcome,accepted:stage.completedObligationCount,newObligations:stage.newObligationCount,durationMs:stage.durationMs,core:stage.work.coreBranches,continuation:stage.work.standaloneBranches,total:stage.branchesExplored,protectedEquality:stage.protectedEqualityProof??null,hard:stage.newHardViolationCount,required:stage.newRequiredViolationCount,visible:stage.visibleProposalTaskIds,supportingCount:stage.supportingTaskCount,ephemeralCount:stage.ephemeralSupportingPlacements.length,sodexo:stage.sodexoMeals?.count,globalMealGate:stage.sodexoMeals?.globalMealGate,scheduling:{deferred:stage.standaloneDiagnostic?.bundleContinuationDeferrals,resumed:stage.standaloneDiagnostic?.bundleContinuationResumptions,pending:stage.standaloneDiagnostic?.bundlePendingContinuations},fingerprint:stage.acceptedStageFingerprint,witnesses:stage.futureStructuralWitnesses.map((w:any)=>({kind:w.kind,fingerprint:w.fingerprint,tasks:w.tasks?.length,meals:w.participantMeals?.length}))}));
const summary={status:result.status,accepted:result.completedObligationCount,stageCount:result.stageCount,wallMs:performance.now()-started,materialDigest:createHash('sha256').update(JSON.stringify(collectiveClosureDeterministicMaterial(result))).digest('hex'),finalFingerprint:result.deterministicFingerprint,firstBlocker:result.firstBlocker,stages};
